import * as React from "react";

import { Badge } from "../ui/badge";
import { Button } from "../ui/button";
import { List, ListRow, ListSection } from "../ui/list";
import { useInFrame } from "../lib/frame-context";

import styles from "./patterns.module.css";

export interface ActivityEvent {
  id: string;
  actor: string;
  actorKind?: "person" | "machine" | "agent";
  /** What the actor did, written to follow the actor's name: "updated stripe_api_key". */
  summary: React.ReactNode;
  time: string;
  /** Badges beside the summary, such as the environment or the result of the change. */
  badge?: React.ReactNode;
}
export interface ActivityDay {
  label: string;
  events: readonly ActivityEvent[];
}

export type ActivityLogProps = {
  days: readonly ActivityDay[];
  /** Every event that matches, for the "Showing x of y" footer. Leave it out for keyset APIs that only know whether more exist. */
  total?: number;
  /** Whether another page exists. Defaults to fewer events shown than total. */
  hasMore?: boolean;
  loading?: boolean;
  onLoadMore?: () => void;
  label?: string;
  /** What renders when there are no events. */
  empty?: React.ReactNode;
  /** Shows each day's event count and the "Showing" footer. Turn it off for a short log, such as a card on a detail page, where the counts only repeat what the rows show. */
  counts?: boolean;
  /** A hairline between day groups, none above the first or below the last. Turn it off where the log sits right against other ruled rows. */
  dividers?: boolean;
};

const kindLabel = { person: "", machine: "Machine", agent: "Agent" } as const;
const plural = (count: number) =>
  `${count} ${count === 1 ? "event" : "events"}`;

export const ActivityLog = ({
  days,
  total,
  hasMore,
  loading = false,
  onLoadMore,
  label = "Activity",
  empty = "No activity yet",
  counts = true,
  dividers = true,
}: ActivityLogProps) => {
  const inFrame = useInFrame("ActivityLog");
  const shown = days.reduce((sum, day) => sum + day.events.length, 0);
  const more = hasMore ?? (total !== undefined && shown < total);
  let footer: React.ReactNode;
  if (more && onLoadMore)
    footer = (
      <Button
        variant="outline"
        size="sm"
        loading={loading}
        onClick={onLoadMore}
      >
        Load more
      </Button>
    );
  else if (!counts) footer = undefined;
  else if (total !== undefined) footer = `Showing ${shown} of ${total} events`;
  else if (shown > 0) footer = `Showing ${plural(shown)}`;
  return (
    <div
      data-slot="activity-log"
      data-dividers={dividers || undefined}
      className={styles.activityLog}
    >
      <List
        label={label}
        variant={inFrame ? undefined : "plain"}
        size="sm"
        loading={loading}
        empty={empty}
        footer={footer}
      >
        {days.map((day) => (
          <ListSection
            key={day.label}
            label={day.label}
            meta={counts ? plural(day.events.length) : undefined}
          >
            {day.events.map((event) => {
              const kind = event.actorKind ?? "person";
              const badges = (kind !== "person" || event.badge) && (
                <span className={styles.activityBadges}>
                  {kind !== "person" && <Badge>{kindLabel[kind]}</Badge>}
                  {event.badge}
                </span>
              );
              return (
                <ListRow
                  key={event.id}
                  value={event.id}
                  label={event.actor}
                  title={
                    <>
                      <span
                        data-slot="activity-actor"
                        className={styles.activityActor}
                      >
                        {event.actor}
                      </span>{" "}
                      <span className={styles.activitySummary}>
                        {event.summary}
                      </span>
                    </>
                  }
                  badge={badges || undefined}
                  meta={event.time}
                />
              );
            })}
          </ListSection>
        ))}
      </List>
    </div>
  );
};

.pattern {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-12);
  min-width: 0;
}
.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--cipher-space-12);
}
.toolbarText {
  margin: 0;
  color: var(--cipher-text2);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
}
.stage {
  position: relative;
  padding-bottom: calc(var(--cipher-space-48) + var(--cipher-space-32));
}
.queueTitleLine,
.queueSmallLine {
  display: flex;
  align-items: center;
}
.queueTitleLine {
  min-height: var(--cipher-type-row-title-line-height);
}
.queueSmallLine {
  min-height: var(--cipher-type-small-line-height);
}
.activityLog [data-list-row] {
  border-bottom-color: transparent;
}
.activityLog [data-slot="list"][data-size] [data-slot="list-section-head"] {
  padding-inline: var(--cipher-space-surface-inset-sm);
}
.activityLog[data-dividers] [data-slot="list-section"] + [data-slot="list-section"] {
  border-top: var(--cipher-size-control-border) solid var(--cipher-line-soft);
}
.activityActor {
  color: var(--cipher-ink);
}
.activitySummary {
  color: var(--cipher-text2);
  font-weight: var(--cipher-type-body-font-weight);
}
.activityBadges {
  display: inline-flex;
  align-items: center;
  gap: var(--cipher-space-4);
}
